#!/usr/bin/env python3
"""
Round 113b (culprits), 29 September 2026. Needs round 112b.

Crowded point layers as banded, raised ground (hypsometric), slimmer site-map dots, and a ring of ready-made colour themes made kind by kind (points, shapes, highlights) with the wheel.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 113b (29 September)\n\nNeeds round 112b. No tiles patch. No app.js?v= bump.\n\n- Crowded point rows (owner chose "tinted bands and raised"): a point row of\n  DENSITY_MIN (300) points or more gets a density surface whenever shown:\n  ${id}__crowd-tint, raster from relief://<rid>/col in RELIEF_BANDS with\n  contour lines, raster-opacity by zoom DENSITY_FADE (0.8 wide out, gone by\n  zoom 10), under the row\'s marks; the hillshade and raised ground follow\n  "Raise figures as heights" as before (bands stay flat with it off).\n  densityKey: a band strip under the row. reliefPoints weighs merged marks by\n  _count, point_count, n, schools or count (numbers only) and counts a mark\n  read twice once; vector rows recount on moveend while banded, and wait for\n  their squares (map idle, up to 4 tries). pointReliefGrid smooths three\n  passes of radius 2 (about 200 km, was two of radius 1).\n- Site-map dots slimmer wide out: radius 0.42r at z1, 0.58r z4, 0.82r z7, r z10.\n- Themes kind by kind (owner chose "preset themes + wheel"): THEME_KINDS\n  points / shapes / highlights; themeKindOf (circle, symbol, heatmap = points;\n  source boundaries or -lift = highlights; else shapes); themeStepsFor;\n  themeWrap and themeApply use the kind\'s matrix. THEME_PRESETS (Deep ocean,\n  Glacier, Cobalt, Slate and bone, Basalt, Dusk, Signal, Ink), each a wheel\n  point per kind (kindTheme), in a ring round the wheel (.tw-ring, split\n  swatches); chips All / Points / Shapes / Highlights pick what the wheel\n  turns (THEME_TARGET, THEME_WHEEL, localStorage culprits-theme-kinds).\n  themeKeys gives shape and national rows their own CSS filter (:has()).\n\n'
HEAD = '## Round 113b (29 September)'


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round113b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 112b" not in text:
        sys.exit("round113b: round 112b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round113b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round113b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round113b: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round ")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
